{"SMALL_TALK","reg=swat|st=friendly,neutral",{"Quiet day, don't say it out loud","You see the sky last night? Not a single plane","Not much to say"}},
{"SMALL_TALK","reg=military,elite|st=friendly,neutral",{"Weather's holding, good for us, good for them","Haven't seen a jet in days - strange","Mosquitoes out here are bigger than my rifle"}},
{"SMALL_TALK","reg=civilian,family,worker,rescue|st=friendly,neutral",{"The heat's awful, I keep thinking it'll break","My tomatoes are coming in, nobody to give them to","Funny, I keep worrying about the electric bill"}},
{"SMALL_TALK","reg=raider,outlaw,gang,club,crime,prison|st=friendly,neutral",{"Hot enough to fry an egg on the hood","Gas stations are dry for miles - you heard?","Ever notice none of the traffic lights work? I love it"},false,{[2]="GENERIC"}},
